#!/usr/bin/env python3
"""Generate all 800 Bible trivia questions as JSON."""
import json, os

N = None  # Python None = JSON null

def q(diff, cat, num, question, options, ans, exp, ref=N, book=N, topic=N):
    pts = {"beginners": 10, "intermediate": 20, "skilled": 30, "expert": 50}[diff]
    prefix = {"beginners": "beg", "intermediate": "int", "skilled": "skl", "expert": "exp"}
    cat_prefix = {"full_bible": "fb", "new_testament": "nt", "old_testament": "ot", "apologetics": "ap"}
    return {
        "questionId": f"{prefix[diff]}_{cat_prefix[cat]}_{num:03d}",
        "question": question,
        "options": json.dumps(options),
        "correctAnswer": ans,
        "explanation": exp,
        "scriptureReference": ref,
        "difficulty": diff,
        "category": cat,
        "basePoints": pts,
        "bibleBook": book,
        "topic": topic,
    }

# Load existing 100 questions
with open('prisma/questions/part1_beginners.json', 'r') as f:
    questions = json.load(f)

