q(D,C,34,"Who wrote 'The Reason for God'?",["Timothy Keller","C.S. Lewis","William Lane Craig","Francis Collins"],0,"Timothy Keller wrote 'The Reason for God: Belief in an Age of Skepticism.'",N,N,"Apologetics Literature"),
q(D,C,35,"Who wrote 'The Case for Christ'?",["Lee Strobel","Timothy Keller","William Lane Craig","Ravi Zacharias"],0,"Lee Strobel, a former legal journalist, wrote 'The Case for Christ' after investigating the evidence.",N,N,"Apologetics Literature"),
