q(D,C,37,"What is 'theistic evolution' (evolutionary creationism)?",["Atheism + evolution","The view that God used evolution as His creative mechanism","Creation without God","Intelligent design only"],1,"Theistic evolution holds that God is the Creator who used evolutionary processes.","Genesis 1:1","Genesis","Science & Faith"),
q(D,C,38,"What is 'old earth creationism'?",["The earth is 6,000 years old","The earth is ancient, but God created life directly (not through evolution)","The earth has always existed","The earth was created instantly"],1,"Old earth creationism accepts an ancient earth but rejects macroevolution.","Genesis 1:1","Genesis","Science & Faith"),
q(D,C,39,"What is 'young earth creationism'?",["The earth is ancient","The earth is roughly 6,000-10,000 years old, based on a literal reading of Genesis","The earth is 4.5 billion years old","The earth was created yesterday"],1,"Young earth creationism interprets Genesis 1 literally, dating creation to ~6,000-10,000 years ago.","Genesis 1:1","Genesis","Science & Faith"),
q(D,C,40,"What is 'intelligent design' (ID)?",["A religious doctrine","The scientific observation that certain features of nature are best explained by an intelligent cause","A type of creationism","A political movement"],1,"ID argues that features like irreducible complexity and specified information point to intelligence.",N,N,"Science & Faith"),
q(D,C,41,"What is 'irreducible complexity'?",["A type of simplicity","A system that cannot function if any part is removed, suggesting it was designed as a whole","A type of evolution","A philosophical concept"],1,"Michael Behe's concept: some biological systems (e.g., the bacterial flagellum) are irreducibly complex.",N,N,"Science & Faith"),
q(D,C,42,"What is 'specified complexity'?",["Random patterns","Information that is both complex and specified, pointing to intelligent design","A type of math","A biological term"],1,"William Dembski's concept: specified complexity (like DNA) points to intelligent causation.",N,N,"Science & Faith"),
q(D,C,43,"What is the 'anthropic principle' in cosmology?",["Humans are the center","The universe's physical constants appear fine-tuned for the existence of intelligent life","Humans created the universe","The universe is anthropomorphic"],1,"The anthropic principle notes that the universe's parameters are precisely set for life.",N,N,"Science & Faith"),
