q(D,C,3,"What is the 'Q source' (Quelle)?",["A manuscript","A hypothetical collection of Jesus' sayings used by Matthew and Luke, not found in Mark","A type of Gospel","A biblical language"],1,"Q (from German Quelle, 'source') is a hypothetical document of ~235 verses of Jesus' sayings.",N,N,"Biblical Studies"),
q(D,C,4,"What is the 'Farrer hypothesis'?",["Mark first, then Matthew used Mark, then Luke used Mark + Matthew","A theory about John's Gospel","A theory about Paul's letters","A theory about the canon"],0,"Farrer hypothesis: Mark → Matthew → Luke (Luke used both Mark and Matthew, no Q needed).",N,N,"Biblical Studies"),
q(D,C,5,"What is the 'four-source hypothesis' (Streeter)?",["One source","Mark + Q + M (Matthew's special material) + L (Luke's special material)","Four Gospels only","Four manuscripts"],1,"Streeter's four-source hypothesis: Mark + Q + M (Matthew-only) + L (Luke-only).",N,N,"Biblical Studies"),
