q(D,C,13,"What is the 'Federal Vision' theology?",["A vision for the future","A controversial movement emphasizing covenantal objectivity and baptismal efficacy","A political vision","A type of eschatology"],1,"Federal Vision emphasizes the objectivity of the covenant and baptism, but is criticized for blurring the law/gospel distinction.",N,N,"Theology"),
q(D,C,14,"What is the 'Paul Within Judaism' perspective?",["Paul was Jewish","Paul remained within Second Temple Judaism, not founding a new religion","Paul converted to Christianity","Paul rejected Judaism"],1,"The 'Paul Within Judaism' perspective argues Paul remained a Torah-observant Jew, not converting to a new religion.","Acts 28:17","Acts","Theology"),
q(D,C,15,"What is the 'apocalyptic Paul'?",["Paul wrote Revelation","Paul's theology is centered on the apocalyptic in-breaking of God's new age in Christ","Paul was fearful","Paul was an apocalyptic writer only"],1,"The apocalyptic Paul (J. Christiaan Beker, Ernst Käsemann) sees Paul's theology as centered on cosmic apocalyptic events.","Galatians 1:4","Galatians","Theology"),
q(D,C,16,"What is ' pistis Christou' debate?",["A debate about Paul's faith","The debate over whether 'pistis Christou' means 'faith in Christ' (objective genitive) or 'faith(fulness) of Christ' (subjective genitive)","A debate about faith vs. works","A debate about Christology"],1,"The pistis Christou debate: does it mean 'faith in Christ' (objective) or 'the faithfulness of Christ' (subjective)?","Galatians 2:16","Galatians","Theology"),
q(D,C,17,"What is the social-scientific approach to the NT?",["Using sociology to study the NT","Applying insights from anthropology, sociology, and economics to understand the NT world","Using science to prove miracles","Using statistics on manuscripts"],1,"Social-scientific criticism applies models from sociology and anthropology to understand the NT social context.",N,N,"Biblical Studies"),
